#include "RAWFILE.H"
#include "chunkio.h"
#include <cstdint>
#include <cstdlib>
#include <cstdio>
#include <cstring>
#include <sys/stat.h>
#include <unistd.h>
static_assert(sizeof(ChunkHeader)==8,"Chunk disk header must remain eight bytes on host and ARM");
static void check(bool v){static int index=0;++index;if(!v){fprintf(stderr,"chunk check %d failed\n",index);std::abort();}}
int main(){const char* path="chunk-test.dat";RawFileClass f(path);check(f.Open(FileClass::WRITE));{ChunkSaveClass save(&f);check(save.Begin_Chunk(0x11223344));check(save.Begin_Chunk(0x55667788));const unsigned char bytes[]={1,2,3,4,5};check(save.Write(bytes,5)==5);check(save.End_Chunk());check(save.End_Chunk());}f.Close();check(f.Open(FileClass::READ));unsigned char actual[21];check(f.Read(actual,21)==21);const unsigned char expected[]={0x44,0x33,0x22,0x11,13,0,0,0x80,0x88,0x77,0x66,0x55,5,0,0,0,1,2,3,4,5};check(std::memcmp(actual,expected,21)==0);check(f.Seek(0,SEEK_SET)==0);{ChunkLoadClass load(&f);check(load.Open_Chunk());check(load.Cur_Chunk_ID()==0x11223344);check(load.Open_Chunk());check(load.Cur_Chunk_ID()==0x55667788);check(load.Cur_Chunk_Length()==5);unsigned char bytes[5];check(load.Read(bytes,5)==5);check(std::memcmp(bytes,expected+16,5)==0);check(load.Close_Chunk());check(load.Close_Chunk());check(!load.Open_Chunk());}f.Close();{FILE* shortfile=std::fopen(path,"wb");check(shortfile!=nullptr);check(std::fwrite("abc",1,3,shortfile)==3);check(std::fclose(shortfile)==0);}f.Bias(0);check(f.Open(FileClass::READ));{ChunkLoadClass shortload(&f);check(!shortload.Open_Chunk());check(f.Seek(0,SEEK_CUR)==0);check(!shortload.Close_Chunk());}f.Close();{FILE* partial=std::fopen(path,"wb");check(partial!=nullptr);check(std::fwrite(expected,1,20,partial)==20);check(std::fclose(partial)==0);}f.Bias(0);check(f.Open(FileClass::READ));{ChunkLoadClass truncated(&f);check(!truncated.Open_Chunk());check(f.Seek(0,SEEK_CUR)==0);}f.Close();f.Bias(0);check(f.Open(FileClass::WRITE));{ChunkSaveClass save(&f);check(!save.Begin_Micro_Chunk(1));check(save.Begin_Chunk(0x1234));check(save.Begin_Micro_Chunk(7));check(save.Write("abc",3)==3);check(save.Write("abc",256)==0);check(save.End_Micro_Chunk());check(save.Begin_Micro_Chunk(8));check(save.End_Micro_Chunk());check(save.End_Chunk());}f.Close();check(f.Open(FileClass::READ));{const unsigned char golden[]={0x34,0x12,0,0,7,0,0,0,7,3,'a','b','c',8,0};unsigned char disk[15];check(f.Read(disk,15)==15);check(std::memcmp(disk,golden,15)==0);check(f.Seek(0,SEEK_SET)==0);ChunkLoadClass load(&f);check(!load.Open_Micro_Chunk());check(load.Open_Chunk());check(load.Open_Micro_Chunk());check(load.Cur_Micro_Chunk_ID()==7);char letter=0;check(load.Read(&letter,1)==1 && letter=='a');check(load.Close_Micro_Chunk());check(load.Open_Micro_Chunk());check(load.Cur_Micro_Chunk_ID()==8 && load.Cur_Micro_Chunk_Length()==0);check(load.Close_Micro_Chunk());check(!load.Open_Micro_Chunk());check(load.Close_Chunk());}f.Close();f.Bias(0);{unsigned char invalid[]={0x34,0x12,0,0,4,0,0,0,7,3,'a','b'};FILE* out=std::fopen(path,"wb");check(out!=nullptr);check(std::fwrite(invalid,1,sizeof(invalid),out)==sizeof(invalid));check(std::fclose(out)==0);}check(f.Open(FileClass::READ));{ChunkLoadClass load(&f);check(load.Open_Chunk());check(!load.Open_Micro_Chunk());check(f.Seek(0,SEEK_CUR)==8);check(load.Close_Chunk());}f.Close();std::remove(path);puts("PASS original nested chunk IO exact21diskbytes");}
